import Foundation
import Testing
@testable import DocCStatic

/// The ways the link fixture is generated by the end-to-end tests.
enum LinkFixtureVariant: String, CaseIterable, Sendable, CustomTestStringConvertible {
    /// The dependency is not documented and no external documentation is configured.
    case plain

    /// External documentation is configured for the dependency's package name.
    case packageKey

    /// External documentation is configured for the dependency's module name.
    case moduleKey

    /// The dependency is documented alongside the package.
    case includedDependency

    /// The name of the dependency package of the link fixture.
    static let dependencyPackage = "FixturePalette"

    /// The name of the module of the dependency package.
    static let dependencyModule = "FixtureColours"

    /// The base URL configured for the dependency's package name.
    static let packageBaseURL = "https://example.com/palette"

    /// The base URL configured for the dependency's module name.
    static let moduleBaseURL = "https://example.com/colours"

    /// The base URL that links to the dependency's pages start with, if any.
    var baseURL: String? {
        switch self {
        case .packageKey: Self.packageBaseURL
        case .moduleKey: Self.moduleBaseURL
        case .plain, .includedDependency: nil
        }
    }

    var testDescription: String { rawValue }

    /// Returns the generated documentation of the link fixture for this variant.
    func output() async throws -> GeneratedFixture {
        try await FixtureDocumentation.links.output(variant: rawValue) { configuration in
            switch self {
            case .plain:
                configuration.dependencyPolicy = .none
            case .packageKey:
                configuration.dependencyPolicy = .none
                configuration.externalDocumentationURLs = [
                    Self.dependencyPackage: URL(string: Self.packageBaseURL + "/")!
                ]
            case .moduleKey:
                configuration.dependencyPolicy = .none
                configuration.externalDocumentationURLs = [
                    Self.dependencyModule: URL(string: Self.moduleBaseURL)!
                ]
            case .includedDependency:
                configuration.dependencyPolicy = .all
            }
        }
    }
}

/// Returns the values of an attribute in HTML.
///
/// - Parameters:
///   - attribute: The attribute name, such as `href`.
///   - html: The HTML to search.
/// - Returns: The attribute values in document order.
func linkAttributeValues(of attribute: String, in html: String) -> [String] {
    let pattern = " \(attribute)=\""
    var values: [String] = []
    var remainder = html[...]
    while let start = remainder.range(of: pattern) {
        let valueStart = start.upperBound
        guard let end = remainder[valueStart...].firstIndex(of: "\"") else { break }
        values.append(String(remainder[valueStart..<end]))
        remainder = remainder[end...]
    }
    return values
}

/// Returns the relative links of a generated page whose target file does not exist.
///
/// - Parameters:
///   - page: The generated HTML file.
///   - fixture: The generated site.
/// - Returns: The dead links.
/// - Throws: An error if the page cannot be read.
func deadRelativeLinks(in page: URL, of fixture: GeneratedFixture) throws -> [String] {
    let html = try String(contentsOf: page, encoding: .utf8)
    let directory = page.deletingLastPathComponent()
    var dead: [String] = []
    for link in linkAttributeValues(of: "href", in: html) + linkAttributeValues(of: "src", in: html) {
        let unescaped = link.replacingOccurrences(of: "&#39;", with: "'").replacingOccurrences(of: "&amp;", with: "&")
        // Links with a scheme, such as `https:`, and fragments of the page are not files
        if let colon = unescaped.firstIndex(of: ":"), !unescaped[..<colon].contains(where: { "/().".contains($0) }) {
            continue
        }
        guard !unescaped.isEmpty, !unescaped.hasPrefix("#") else { continue }
        let path = String(unescaped.split(separator: "#", maxSplits: 1, omittingEmptySubsequences: false)[0])
            .split(separator: "?", maxSplits: 1, omittingEmptySubsequences: false)[0]
        guard !path.isEmpty else { continue }
        let decoded = String(path).removingPercentEncoding ?? String(path)
        let target = directory.appendingPathComponent(decoded).standardizedFileURL
        var isDirectory: ObjCBool = false
        let exists = FileManager.default.fileExists(atPath: target.path, isDirectory: &isDirectory)
        if !exists || isDirectory.boolValue {
            dead.append(link)
        }
    }
    return dead
}

/// End-to-end tests that generate documentation of a package whose pages refer to
/// symbols of a dependency, and check where those links point.
@Suite("External Link End-to-End Tests", .serialized)
struct ExternalLinkEndToEndTests {
    /// The fixture's tint property, whose declaration uses a dependency type.
    static let tintPage = "documentation/fixturesketches/sketch/init(tint:)/index.html"

    /// The fixture page whose declaration has a dependency's property wrapper.
    static let shadingPage = "documentation/fixturesketches/sketch/shading/index.html"

    /// The fixture page that conforms to a dependency protocol and lists See Also links.
    static let sketchPage = "documentation/fixturesketches/sketch/index.html"

    /// The fixture page whose declaration uses a type nested in a dependency type.
    static let emphasisPage = "documentation/fixturesketches/sketch/emphasis/index.html"

    /// The fixture page that links to an overloaded method of a dependency.
    static let lightenedPage = "documentation/fixturesketches/sketch/lightened(by:)/index.html"

    /// The fixture page that inherits from a dependency class.
    static let charcoalPage = "documentation/fixturesketches/charcoal/index.html"

    /// The module page of the fixture's documented module with a catalogue.
    static let shapesModulePage = "documentation/fixtureshapes/index.html"

    /// The article of the fixture's documented module with a catalogue.
    static let articlePage = "documentation/fixtureshapes/mixingpaints/index.html"

    @Test("Every relative link of every generated page resolves to an existing file",
          arguments: LinkFixtureVariant.allCases)
    func everyRelativeLinkResolves(variant: LinkFixtureVariant) async throws {
        let fixture = try await variant.output()
        let pages = fixture.files(withExtension: "html")
        #expect(pages.count > 10)
        for page in pages {
            let dead = try deadRelativeLinks(in: page, of: fixture)
            #expect(dead.isEmpty, "Dead links in \(fixture.relativePath(of: page)): \(dead)")
        }
    }

    @Test("Every relative link of the sidebar fixture resolves to an existing file")
    func sidebarFixtureLinksResolve() async throws {
        let fixture = try await FixtureDocumentation.shared.output()
        for page in fixture.files(withExtension: "html") {
            let dead = try deadRelativeLinks(in: page, of: fixture)
            #expect(dead.isEmpty, "Dead links in \(fixture.relativePath(of: page)): \(dead)")
        }
    }

    @Test("Without external documentation, references to the dependency are shown like swift-docc-render shows unresolved ones")
    func plainTextWithoutExternalDocumentation() async throws {
        let fixture = try await LinkFixtureVariant.plain.output()
        for page in fixture.files(withExtension: "html") {
            let html = try String(contentsOf: page, encoding: .utf8)
            #expect(!html.contains("documentation/fixturecolours/"), "Link to the dependency in \(fixture.relativePath(of: page))")
        }
        let tint = try fixture.text(at: Self.tintPage)
        #expect(tint.contains("<span class=\"token-externalParam\">tint</span>: <span class=\"type-identifier-link\"><span>Colour</span></span>"))
        let shading = try fixture.text(at: Self.shadingPage)
        #expect(shading.contains("<span class=\"token-attribute\">@</span><span class=\"token-attribute\">Clamped</span>"))
        let sketch = try fixture.text(at: Self.sketchPage)
        #expect(sketch.contains("<li class=\"relationships-item\"><code>Fixture<wbr>Colours<wbr>.Tinted</code></li>"))
        #expect(sketch.contains("<h3 id=\"conforms-to\" class=\"contenttable-title\">"))
        #expect(sketch.contains("A quick drawing in a single <code class=\"inline-code\">Fixture<wbr>Colours/Colour</code>."))
        let emphasis = try fixture.text(at: Self.emphasisPage)
        #expect(emphasis.contains("<span class=\"type-identifier-link\"><span>Colour</span></span>.<span class=\"type-identifier-link\"><span>Channel</span></span>"))
        let lightened = try fixture.text(at: Self.lightenedPage)
        #expect(lightened.contains("The tint is mixed with <code class=\"inline-code\">Fixture<wbr>Colours/Colour/mixed(with:)-"))
        let charcoal = try fixture.text(at: Self.charcoalPage)
        #expect(charcoal.contains("<li class=\"relationships-item\"><code>Fixture<wbr>Colours<wbr>.Pigment</code></li>"))
        #expect(charcoal.contains("<h3 id=\"inherits-from\" class=\"contenttable-title\">"))
    }

    @Test("A See Also group whose only entry is outside the site is left out with its heading")
    func emptySeeAlsoIsLeftOut() async throws {
        let fixture = try await LinkFixtureVariant.plain.output()
        let charcoal = try fixture.text(at: Self.charcoalPage)
        #expect(!charcoal.contains("id=\"see-also\""))
        #expect(!charcoal.contains("Related Documentation"))
        #expect(!charcoal.contains("href=\"#see-also\""))
        for page in fixture.files(withExtension: "html") {
            let html = try String(contentsOf: page, encoding: .utf8)
            #expect(!html.contains("<div class=\"section-content\"></div>"), "Empty section in \(fixture.relativePath(of: page))")
            #expect(!html.contains("<div class=\"section-content\"><ul class=\"relationships-list inline\"></ul>"),
                    "Empty relationships in \(fixture.relativePath(of: page))")
        }
    }

    @Test("Web links in See Also are listed like swift-docc-render lists them",
          arguments: LinkFixtureVariant.allCases)
    func seeAlsoWebLinks(variant: LinkFixtureVariant) async throws {
        let fixture = try await variant.output()
        let module = try fixture.text(at: Self.shapesModulePage)
        #expect(module.contains("<h3 id=\"Related-Documentation\" class=\"contenttable-title\">"))
        #expect(module.contains("<div class=\"section-content\">\n<div class=\"link-block topic has-inline-element\"><a href=\"https://example.com/colour-theory\" class=\"link\"><span>Colour theory primer</span></a></div>"
            + "\n<div class=\"link-block topic has-inline-element\"><a href=\"https://example.com/paint-mixing\" class=\"link\"><span>Paint mixing guide</span></a></div></div>"))
        #expect(module.contains("<a href=\"#see-also\" class=\"base-link\"><span>See Also</span></a>"))
        let article = try fixture.text(at: Self.articlePage)
        #expect(article.contains("<a href=\"https://example.com/pigments\" class=\"link\"><span>Pigment reference</span></a>"))
        #expect(article.contains("<a href=\"../../../documentation/fixtureshapes/swatch/index.html\" class=\"link has-adjacent-elements\">"))
        let sketch = try fixture.text(at: Self.sketchPage)
        #expect(sketch.contains("<a href=\"https://example.com/sketching\" class=\"link\"><span>Sketching guide</span></a>"))
    }

    @Test("Links within the site are unaffected", arguments: LinkFixtureVariant.allCases)
    func inSiteLinks(variant: LinkFixtureVariant) async throws {
        let fixture = try await variant.output()
        let sketch = try fixture.text(at: Self.sketchPage)
        #expect(sketch.contains("<a href=\"../../../documentation/fixturesketches/sketch/outline()/index.html\" class=\"inline-link\"><code>outline()</code></a>"))
        #expect(sketch.contains("<a href=\"../../../documentation/fixturesketches/outline/index.html\" class=\"inline-link\"><code>Outline</code></a>"))
        let module = try fixture.text(at: Self.shapesModulePage)
        #expect(module.contains("<a href=\"../../documentation/fixtureshapes/mixingpaints/index.html#Choosing-Pigments\" class=\"inline-link\">Choosing Pigments</a>"))
        #expect(module.contains("<a href=\"../../documentation/fixtureshapes/swatch/index.html\" class=\"inline-link\"><code>Swatch</code></a>"))
    }

    @Test("With external documentation, references to the dependency link to its pages",
          arguments: [LinkFixtureVariant.packageKey, .moduleKey])
    func externalLinks(variant: LinkFixtureVariant) async throws {
        let fixture = try await variant.output()
        let base = try #require(variant.baseURL) + "/documentation/fixturecolours"
        let tint = try fixture.text(at: Self.tintPage)
        #expect(tint.contains("<a href=\"\(base)/colour/\" class=\"type-identifier-link\"><code><span>Colour</span></code></a>"))
        let shading = try fixture.text(at: Self.shadingPage)
        #expect(shading.contains("<a href=\"\(base)/clamped/\" class=\"attribute-link\"><span>Clamped</span></a>"))
        let sketch = try fixture.text(at: Self.sketchPage)
        #expect(sketch.contains("<li class=\"relationships-item\"><a href=\"\(base)/tinted/\" class=\"link\"><code>Tinted</code></a></li>"))
        #expect(sketch.contains("A quick drawing in a single <a href=\"\(base)/colour/\" class=\"inline-link\"><code>Colour</code></a>."))
        #expect(sketch.contains("<a href=\"\(base)/tinted/\" class=\"link has-adjacent-elements\">"))
        let emphasis = try fixture.text(at: Self.emphasisPage)
        #expect(emphasis.contains("<a href=\"\(base)/colour/channel/\" class=\"type-identifier-link\"><code><span>Channel</span></code></a>"))
        let lightened = try fixture.text(at: Self.lightenedPage)
        #expect(lightened.contains("The tint is mixed with <a href=\"\(base)/colour/mixed(with:)-"))
        let charcoal = try fixture.text(at: Self.charcoalPage)
        #expect(charcoal.contains("<li class=\"relationships-item\"><a href=\"\(base)/pigment/\" class=\"link\"><code>Pigment</code></a></li>"))
        #expect(charcoal.contains("<h2 id=\"see-also\" class=\"title\">"))
    }

    @Test("A documented dependency is linked within the site")
    func includedDependency() async throws {
        let fixture = try await LinkFixtureVariant.includedDependency.output()
        let tint = try fixture.text(at: Self.tintPage)
        #expect(tint.contains("<a href=\"../../../../documentation/fixturecolours/colour/index.html\" class=\"type-identifier-link\">"))
        let sketch = try fixture.text(at: Self.sketchPage)
        #expect(sketch.contains("<a href=\"../../../documentation/fixturecolours/tinted/index.html\" class=\"link\"><code>Tinted</code></a>"))
    }
}
